case_table=table(pd.DataFrame(case_rows),[('case','Case'),('tract','Tract'),('population','2020 population'),('svi','National SVI rank'),('wildfire','Regional exposure percentile'),('local','Local correspondence'),('status','Evidence')])
matchrows=pd.DataFrame(results['matched_results']);matchrows['gap']=matchrows.urban_minus_rural_pp_100m.map(lambda x:f'{x:+.1f} pp');matchrows['region']=matchrows.region.map(lambda r:names.get(r,r))
